// instead, add a rotated version:
uv2.x += v.x*q1 + v.y*q2;
uv2.y += v.x*q2 - v.y*q1;
// sample previous uFrame
ret = texture( sampler_main, uv2 ).xyz;
// darken over uTime
ret -= 0.004;
}

void main() {
  vec3 ret = vec3(0.0);
  vec2 uv = vUv;
  vec2 uv_orig = vUvOriginal;
  float rad = vRadius;
  float ang = vAngle;
