aa.y *= col.x;
aa.z *= col.y;
aa.x -= 0.95;
aa.y += 0.1;
aa.z += 3.7;
ret4 = ret * aa * GetBlur3(uv) * 20.0;
ret4 *= 0.03;
ret = mix(ret3, ret4, (q1 + q2 + q3)*0.7);
//ret = ret4;
//ret = ret3;
//ret = ret3;
//ret = ret3;
}
  fragColor = vec4(ret, 1.0);
}

