vec2 fragCoord;
// CONV: Center on screen, then try some uAspect correction
uv = (uv * 2.0) - 1.0;
uv *= uAspect.xy;
// CONV: Adjust this to flip the output (±uv.x, ±uv.y)
uv = vec2(uv.x, -uv.y);
// vec2 uv = (2.0 * fragCoord.xy - uTexSize.xy)/uTexSize.y;
float battery = 1.0;
// CONV: iMouse unsupported
// //if (iMouse.x > 1.0 && iMouse.y > 1.0) battery = iMouse.y / uTexSize.y;
// else battery = 0.8;
// if (abs(uv.x) < (9.0 / 16.0))
{
// Grid
float fog = smoothstep(0.1, -0.02, abs(uv.y + 0.2));
vec3 col = vec3(0.0, 0.1, 0.2);
