col += fog * fog * fog;
col = mix(vec3(col.r, col.r, col.r) * 0.5, col, battery * 0.7);
ret = vec4(col,1.0);
}
// else ret = vec4(0.0, 0.0, 0.0, 0.0);
}
shader_body {
