float3 mod_conv(float3 x, float3 y) { return x - y * floor(x / y); }
float4 mod_conv(float4 x, float4 y) { return x - y * floor(x / y); }
float heightMap(in float2 p) {
p *= 3.;
float2 h = float2(p.x + p.y*.57735, p.y*1.1547);
float2 fh = floor(h);
float2 f = h - fh; h = fh;
float c = frac((h.x + h.y)/3.);
h =  c<.666 ?   c<.333 ?  h  :  h + 1.  :  h  + step(f.yx, f);
p -= float2(h.x - h.y*.5, h.y*.8660254);
c = frac(cos(dot(h, float2(41, 289)))*43758.5453);
// Reusing "c."
p -= p*step(c, .5)*2.;
// Equivalent to: if (c<.5) p *= -1.;
p -= float2(-1, 0);
c = dot(p, p);
// Reusing "c" again.
p -= float2(1.5, .8660254);
c = min(c, dot(p, p));
p -= float2(0, -1.73205);
c = min(c, dot(p, p));
